(70, 4, 'Toddler Swing Seat', 'Bucket swing seat with safety belt and adjustable ropes for trees or frames.', 'Check ropes before every use. Adult supervision required.', 24.00, 15, 'unisex', 1, 4, 'assets/images/products/outdoor-sports/toddler-swing-seat-1.jpg', 1, '2026-10-04 03:10:00', '2026-10-04 03:10:00'),
(71, 4, 'Kids Skateboard', 'Maple deck skateboard with grip tape and smooth wheels for beginners.', 'Always wear a helmet and pads. Ride away from traffic.', 29.00, 15, 'boys', 6, 12, 'assets/images/products/outdoor-sports/kids-skateboard-1.jpg', 1, '2026-10-04 10:23:00', '2026-10-04 10:23:00'),
(72, 4, 'Rainbow Roller Skates', 'Adjustable quad roller skates with comfy padding and rainbow details.', 'Wear a helmet, knee and wrist pads. Skate on smooth ground.', 32.00, 15, 'girls', 6, 12, 'assets/images/products/outdoor-sports/rainbow-roller-skates-1.jpg', 1, '2026-10-04 17:36:00', '2026-10-04 17:36:00'),
(73, 4, 'Rainbow Kite', 'Easy-to-fly kite with long colourful tails and 50 m string.', 'Fly in open spaces away from power lines.', 7.50, 40, 'unisex', 5, 12, 'assets/images/products/outdoor-sports/rainbow-kite-1.jpg', 1, '2026-10-05 00:49:00', '2026-10-05 00:49:00'),
(74, 4, 'Junior Badminton Set', 'Two lightweight rackets with shuttlecocks for backyard games.', 'Play in open areas. Replace damaged shuttlecocks.', 12.00, 30, 'unisex', 6, 12, 'assets/images/products/outdoor-sports/junior-badminton-set-1.jpg', 1, '2026-10-05 07:02:00', '2026-10-05 07:02:00'),
(75, 4, 'Kids Bike Helmet', 'Lightweight ventilated helmet with adjustable strap for bikes and scooters.', 'Fit snugly and fasten the strap before every ride.', 16.00, 40, 'unisex', 3, 10, 'assets/images/products/outdoor-sports/kids-bike-helmet-1.jpg', 1, '2026-10-05 14:15:00', '2026-10-05 14:15:00'),
(76, 4, 'Beach Sand Toys Set', 'Bucket, spade, rake and moulds for building sandcastles at the beach or sandbox.', 'Rinse with clean water after the beach.', 8.25, 40, 'unisex', 2, 6, 'assets/images/products/outdoor-sports/beach-sand-toys-set-1.jpg', 1, '2026-10-05 21:28:00', '2026-10-05 21:28:00'),
(77, 4, 'Water Blaster Pump Gun', 'Pump-action water blaster with long range and easy-fill tank.', 'Do not aim at faces. Use outdoors only.', 7.50, 50, 'boys', 5, 12, 'assets/images/products/outdoor-sports/water-blaster-pump-gun-1.jpg', 1, '2026-10-06 04:41:00', '2026-10-06 04:41:00'),
(78, 4, 'Junior Tennis Racket', 'Lightweight junior racket with a cover and two soft tennis balls.', 'Choose the right size for your child''s height.', 14.00, 25, 'unisex', 6, 12, 'assets/images/products/outdoor-sports/junior-tennis-racket-1.jpg', 1, '2026-10-06 11:54:00', '2026-10-06 11:54:00'),
(79, 4, 'Rainbow Hula Hoop', 'Colourful adjustable hula hoop for fitness, dance and playground games.', 'Use in open spaces away from furniture.', 5.50, 40, 'girls', 4, 12, 'assets/images/products/outdoor-sports/rainbow-hula-hoop-1.jpg', 1, '2026-10-06 18:07:00', '2026-10-06 18:07:00'),
(80, 4, 'Giant Bubble Wand Set', 'Bubble wands with non-toxic solution for giant bubbles in the garden.', 'Use outdoors. Do not drink the solution.', 6.00, 50, 'unisex', 3, 8, 'assets/images/products/outdoor-sports/giant-bubble-wand-set-1.jpg', 1, '2026-10-07 01:20:00', '2026-10-07 01:20:00'),
(81, 5, 'RC Off-Road Rock Crawler', 'Rugged 4x4 remote control crawler with shock absorbers and rechargeable battery.', 'Charge fully before first use. Do not drive through water.', 42.00, 15, 'boys', 6, 12, 'assets/images/products/boys-toys/rc-off-road-rock-crawler-1.jpg', 1, '2026-10-01 13:33:00', '2026-10-01 13:33:00'),
(82, 5, 'RC Sports Racing Car', 'Fast remote control sports car with 2.4 GHz remote and LED lights.', 'Charge fully before first use. Drive on smooth surfaces.', 38.00, 15, 'boys', 6, 12, 'assets/images/products/boys-toys/rc-sports-racing-car-1.jpg', 1, '2026-10-01 20:46:00', '2026-10-01 20:46:00'),
(83, 5, 'Monster Truck', 'Big-wheel monster truck with friction motor and strong suspension.', 'Push and release to drive. Wipe clean, do not submerge.', 16.00, 25, 'boys', 4, 10, 'assets/images/products/boys-toys/monster-truck-1.jpg', 1, '2026-10-02 03:59:00', '2026-10-02 03:59:00'),
(84, 5, 'Toy Excavator', 'Construction excavator with moving arm and digging bucket.', 'Play in sand or on the floor. Do not pull the arm too far.', 14.50, 25, 'boys', 3, 8, 'assets/images/products/boys-toys/toy-excavator-1.jpg', 1, '2026-10-02 10:12:00', '2026-10-02 10:12:00'),
(85, 5, 'Construction Wheel Loader', 'Heavy-duty toy wheel loader with lifting front scoop.', 'Wipe clean after sand play.', 16.50, 20, 'boys', 3, 8, 'assets/images/products/boys-toys/construction-wheel-loader-1.jpg', 1, '2026-10-02 17:25:00', '2026-10-02 17:25:00'),
(86, 5, 'Yellow Dump Truck', 'Chunky dump truck with tipping bed for hauling sand and blocks.', 'Wipe clean after outdoor play.', 12.00, 30, 'boys', 3, 7, 'assets/images/products/boys-toys/yellow-dump-truck-1.jpg', 1, '2026-10-03 00:38:00', '2026-10-03 00:38:00'),
(87, 5, 'Dinosaur Figures Set (12 pcs)', 'Detailed dinosaur figures in bright colours with name cards.', 'Use the cards to match each dinosaur to its name.', 15.00, 30, 'boys', 3, 9, 'assets/images/products/boys-toys/dinosaur-figures-set-12-pcs-1.jpg', 1, '2026-10-03 07:51:00', '2026-10-03 07:51:00'),
(88, 5, 'T-Rex Dinosaur Figure', 'Realistic T-Rex figure with textured skin and posable jaw.', 'Wipe clean with a damp cloth.', 9.50, 35, 'boys', 3, 10, 'assets/images/products/boys-toys/t-rex-dinosaur-figure-1.jpg', 1, '2026-10-03 14:04:00', '2026-10-03 14:04:00'),
(89, 5, 'Classic Tin Robot', 'Retro wind-up tin robot that walks and swings its arms.', 'Wind the key gently. Do not overwind.', 18.00, 15, 'boys', 5, 12, 'assets/images/products/boys-toys/classic-tin-robot-1.jpg', 1, '2026-10-03 21:17:00', '2026-10-03 21:17:00'),
(90, 5, 'Retro Robot Friends Set', 'Set of retro-style robots in bright colours for display and play.', 'Keep away from water. Wipe with a dry cloth.', 22.00, 12, 'boys', 5, 12, 'assets/images/products/boys-toys/retro-robot-friends-set-1.jpg', 1, '2026-10-04 04:30:00', '2026-10-04 04:30:00'),
(91, 5, 'Steam Train Railway Set', 'Battery-powered steam locomotive with wagons, track and station.', 'Requires 2 AA batteries. Build the track on a flat floor.', 48.00, 10, 'boys', 4, 10, 'assets/images/products/boys-toys/steam-train-railway-set-1.jpg', 1, '2026-10-04 11:43:00', '2026-10-04 11:43:00'),
(92, 5, 'Rescue Fire Truck', 'Rescue vehicle with siren sounds, lights and rolling wheels.', 'Requires 3 AAA batteries (included). Switch off after play.', 13.50, 25, 'boys', 3, 8, 'assets/images/products/boys-toys/rescue-fire-truck-1.jpg', 1, '2026-10-04 18:56:00', '2026-10-04 18:56:00'),
(93, 5, 'Red Biplane Toy', 'Classic red biplane with spinning propeller for high-flying adventures.', 'Spin the propeller gently. Keep away from water.', 11.50, 25, 'boys', 3, 9, 'assets/images/products/boys-toys/red-biplane-toy-1.jpg', 1, '2026-10-05 01:09:00', '2026-10-05 01:09:00'),
(94, 5, 'Building Bricks Set (500 pcs)', 'Compatible building bricks in many colours with an ideas booklet.', 'Small parts: not for children under 3. Sort bricks by colour.', 26.00, 25, 'boys', 5, 12, 'assets/images/products/boys-toys/building-bricks-set-500-pcs-1.jpg', 1, '2026-10-05 08:22:00', '2026-10-05 08:22:00'),
(95, 5, 'Racing Car Track Set', 'Flexible race track with curves, start line and two racing cars.', 'Build the track on the floor. Keep small parts away from toddlers.', 28.00, 20, 'boys', 4, 10, 'assets/images/products/boys-toys/racing-car-track-set-1.jpg', 1, '2026-10-05 15:35:00', '2026-10-05 15:35:00'),
(96, 5, 'Mini Camera Drone', 'Easy-to-fly mini drone with altitude hold, one-key take-off and HD camera.', 'Fly outdoors in calm weather. Adult supervision required.', 79.00, 8, 'boys', 10, 12, 'assets/images/products/boys-toys/mini-camera-drone-1.jpg', 1, '2026-10-05 22:48:00', '2026-10-05 22:48:00'),
(97, 5, 'Pirate Ship Model', 'Detailed wooden pirate ship model with sails and cannons.', 'Display piece. Keep away from water and dust regularly.', 35.00, 10, 'boys', 6, 12, 'assets/images/products/boys-toys/pirate-ship-model-1.jpg', 1, '2026-10-06 05:01:00', '2026-10-06 05:01:00'),
(98, 5, 'Police Patrol Car', 'Friendly police car with rolling wheels and rounded edges for little hands.', 'Wipe clean with a damp cloth.', 9.00, 35, 'boys', 2, 6, 'assets/images/products/boys-toys/police-patrol-car-1.jpg', 1, '2026-10-06 12:14:00', '2026-10-06 12:14:00'),
(99, 5, 'Die-Cast Cars Collection', 'Metal toy cars with free-rolling wheels and classic designs.', 'Small parts may come loose: check cars regularly.', 12.00, 40, 'boys', 3, 10, 'assets/images/products/boys-toys/die-cast-cars-collection-1.jpg', 1, '2026-10-06 19:27:00', '2026-10-06 19:27:00'),
(100, 5, 'Yellow School Bus', 'Die-cast school bus with opening door and pull-back motor.', 'Pull back and release to drive.', 10.50, 30, 'boys', 3, 8, 'assets/images/products/boys-toys/yellow-school-bus-1.jpg', 1, '2026-10-07 02:40:00', '2026-10-07 02:40:00');
