INSERT INTO `reviews` (`product_id`, `user_id`, `rating`, `comment`, `is_visible`, `created_at`) VALUES
(10, 1, 5, 'Beautiful wooden pieces, my son learned the moves in one weekend.', 1, '2026-10-15 10:00:00'),
(10, 4, 4, 'Good quality board, the folding hinge could be a bit stronger.', 1, '2026-10-16 03:00:00'),
(1, 1, 5, 'Bright colours and very solid. Great for practising maths at home.', 1, '2026-10-16 20:00:00'),
(5, 4, 5, 'My daughter checks every leaf in the garden now. Clear image and easy to focus.', 1, '2026-10-17 13:00:00'),
(61, 1, 5, 'Light enough for my 3 year old to carry. He was gliding after two days.', 1, '2026-10-18 06:00:00'),
(44, 4, 5, 'So soft! It is the first thing she takes to bed every night.', 1, '2026-10-18 23:00:00'),
(24, 1, 4, 'Lovely dollhouse, assembly took about an hour but the result is worth it.', 1, '2026-10-19 16:00:00'),
(81, 4, 5, 'Climbs everything in the backyard and the battery lasts long.', 1, '2026-10-20 09:00:00'),
(94, 1, 5, 'Fits with our other bricks perfectly, lots of colours.', 1, '2026-10-21 02:00:00'),
