-- =====================================================================
-- Kiddo's - catalog data (5 categories, 100 products, 200 product images)
-- Images live in the project folder: assets/images/...
--   assets/images/products/<category-slug>/<product-slug>-1.jpg / -2.jpg
--   assets/images/categories/<category-slug>.jpg
--   assets/images/age-groups/<age-group-slug>.jpg
-- Run it in phpMyAdmin on the `kiddos` database (SQL tab -> paste -> Go).
-- It removes the old dummy products, images, reviews and discounts and the
-- 12 extra categories, then inserts the new catalog. Users and orders stay.
-- Photos: Unsplash (free license).
-- =====================================================================

-- Safe to run more than once: it clears the catalog tables first.

-- ---------- 1) Remove old dummy data ----------
DELETE FROM `images`;
DELETE FROM `reviews`;
DELETE FROM `discounts`;
DELETE FROM `products`;
DELETE FROM `categories` WHERE `id` > 5;

-- ---------- 2) The 5 categories ----------
-- `image` column: picture of each category (nullable, so no code depends on it)
ALTER TABLE `categories` ADD COLUMN IF NOT EXISTS `image` varchar(255) DEFAULT NULL AFTER `icon`;

UPDATE `categories` SET `name` = 'Educational Toys', `slug` = 'educational-toys', `description` = 'Learning toys that build counting, reading, science and problem-solving skills', `icon` = 'bi bi-mortarboard', `image` = 'assets/images/categories/educational-toys.jpg' WHERE `id` = 1;
UPDATE `categories` SET `name` = 'Wooden Toys', `slug` = 'wooden-toys', `description` = 'Timeless, eco-friendly wooden toys made to last for years of play', `icon` = 'bi bi-tree', `image` = 'assets/images/categories/wooden-toys.jpg' WHERE `id` = 2;
UPDATE `categories` SET `name` = 'Girls Toys', `slug` = 'girls-toys', `description` = 'Dolls, plush friends, dress-up and creative craft kits', `icon` = 'bi bi-balloon-heart', `image` = 'assets/images/categories/girls-toys.jpg' WHERE `id` = 3;
UPDATE `categories` SET `name` = 'Outdoor & Sports', `slug` = 'outdoor-sports', `description` = 'Bikes, scooters, balls and active outdoor play gear', `icon` = 'bi bi-bicycle', `image` = 'assets/images/categories/outdoor-sports.jpg' WHERE `id` = 4;
UPDATE `categories` SET `name` = 'Boys Toys', `slug` = 'boys-toys', `description` = 'Vehicles, robots, dinosaurs and building sets for little adventurers', `icon` = 'bi bi-car-front', `image` = 'assets/images/categories/boys-toys.jpg' WHERE `id` = 5;

-- ---------- 3) Age group pictures (old ones pointed to missing files) ----------
UPDATE `age_groups` SET `image` = 'assets/images/age-groups/toddlers.jpg' WHERE `slug` = 'toddlers';
UPDATE `age_groups` SET `image` = 'assets/images/age-groups/little-kids.jpg' WHERE `slug` = 'little-kids';
UPDATE `age_groups` SET `image` = 'assets/images/age-groups/big-kids-tweens.jpg' WHERE `slug` = 'big-kids-tweens';

-- ---------- 4) 100 products (20 per category) ----------
ALTER TABLE `products` AUTO_INCREMENT = 1;

-- ---------- 5) Two images per product ----------
ALTER TABLE `images` AUTO_INCREMENT = 1;

-- ---------- 6) Discounts (current season) ----------
ALTER TABLE `discounts` AUTO_INCREMENT = 1;

-- ---------- 7) Reviews from the existing customer accounts ----------
ALTER TABLE `reviews` AUTO_INCREMENT = 1;

-- ---------- 8) Next ids continue after the new data ----------
ALTER TABLE `products` AUTO_INCREMENT = 101;
ALTER TABLE `categories` AUTO_INCREMENT = 6;
